// EDUVERSE chunk: pilot — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_PILOT = [{"bahas":"Penulis menghasilkan naskah sebagai karyanya, sama seperti pelukis menghasilkan lukisan sebagai karyanya. Pasangan lain menunjukkan hubungan orang dengan tempat bekerja atau orang dengan pihak yang dilayani, bukan hubungan pencipta dengan karya yang dihasilkan.","id":"PU01","kunci":2,"opsi":["Koki : Restoran","Guru : Murid","Pelukis : Lukisan","Dokter : Rumah Sakit","Petani : Sawah"],"soal":"Lengkapilah analogi berikut: Penulis : Naskah = ... Pasangan kata manakah yang memiliki hubungan yang sama dengan pasangan kata tersebut?","subtes":"Penalaran Umum"},{"bahas":"Semua bus kota baru termasuk kendaraan listrik, dan semua kendaraan listrik tidak mengeluarkan asap knalpot, sehingga semua bus kota baru juga tidak mengeluarkan asap knalpot. Pernyataan lain bertentangan dengan premis atau membalik hubungan yang dinyatakan premis.","id":"PU02","kunci":4,"opsi":["Sebagian bus kota baru mengeluarkan asap knalpot.","Semua kendaraan listrik adalah bus kota baru.","Tidak ada kendaraan listrik yang merupakan bus kota baru.","Sebagian kendaraan listrik mengeluarkan asap knalpot.","Semua bus kota baru tidak mengeluarkan asap knalpot."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua kendaraan listrik tidak mengeluarkan asap knalpot. Premis 2: Semua bus kota baru adalah kendaraan listrik. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Eko menempati posisi 5. Budi tepat di depan Cita sehingga Budi dan Cita membentuk pasangan berurutan pada posisi 1 sampai 4, sedangkan Andi harus berada di depan Budi. Susunan yang memenuhi semua syarat hanya Andi-Budi-Cita-Dina-Eko dan Andi-Dina-Budi-Cita-Eko. Pada semua susunan yang memenuhi syarat, Andi selalu menempati posisi 1, sedangkan posisi Budi, Cita, dan Dina dapat berubah.","id":"PU03","kunci":0,"opsi":["Andi berada di posisi paling depan.","Budi berada di posisi kedua.","Cita berada di posisi ketiga.","Dina berada tepat di belakang Cita.","Dina berada di posisi kedua."],"soal":"Lima siswa, yaitu Andi, Budi, Cita, Dina, dan Eko, antre membeli tiket pada posisi 1 (paling depan) sampai posisi 5 (paling belakang). Diketahui: Budi berada tepat di depan Cita; Andi berada di depan Budi; Eko berada di posisi paling belakang; Dina tidak berada di posisi paling depan. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"id":"PU04","subtes":"Penalaran Umum","soal":"Perhatikan pola bilangan berikut: 2, 5, 10, 17, 26, ... Bilangan berikutnya dalam pola tersebut adalah ...","opsi":["35","37","39","33","41"],"kunci":1,"bahas":"Setiap suku diperoleh dari kuadrat bilangan berurutan ditambah 1: 1 kuadrat ditambah 1 sama dengan 2, 2 kuadrat ditambah 1 sama dengan 5, 3 kuadrat ditambah 1 sama dengan 10, 4 kuadrat ditambah 1 sama dengan 17, dan 5 kuadrat ditambah 1 sama dengan 26. Suku berikutnya adalah 6 kuadrat ditambah 1, yaitu 37."},{"bahas":"Aturan perpustakaan mewajibkan setiap peminjam buku referensi menunjukkan kartu anggota dan meninggalkan kartu identitas. Rina meminjam buku referensi, sehingga syarat tersebut berlaku untuk Rina. Hal lain seperti status keanggotaan, jumlah buku, atau ketepatan pengembalian tidak dinyatakan dalam informasi yang diberikan.","id":"PU05","kunci":3,"opsi":["Rina adalah anggota perpustakaan yang baru terdaftar pada minggu ini.","Rina meminjam lebih dari satu buku referensi pada hari ini.","Rina akan mengembalikan buku yang dipinjamnya tepat waktu.","Rina menunjukkan kartu anggota dan meninggalkan kartu identitas.","Rina hari ini hanya meminjam buku referensi dan tidak meminjam buku lain."],"soal":"Di sebuah perpustakaan berlaku aturan: setiap anggota yang meminjam buku referensi harus menunjukkan kartu anggota dan meninggalkan kartu identitas. Hari ini Rina meminjam buku referensi di perpustakaan tersebut. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Kata 'di' yang menunjukkan tempat ditulis terpisah dari kata berikutnya, sedangkan 'di' sebagai awalan pada kata kerja pasif ditulis serangkai dengan kata dasarnya. Hanya kalimat tentang belajar di perpustakaan yang mengikuti kaidah tersebut; kalimat lain menulis 'di' tempat secara serangkai atau menulis awalan 'di' secara terpisah.","id":"PPU01","kunci":3,"opsi":["Ibu membeli sayur dipasar pagi ini.","Surat itu di tulis oleh adik kemarin.","Anak-anak bermain dilapangan dekat rumah mereka.","Mereka belajar di perpustakaan setiap sore.","Kucing itu tidur dikursi tamu."],"soal":"Manakah kalimat yang penulisan kata 'di'-nya sudah benar sesuai EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Rantai emas melambangkan sila Kemanusiaan yang adil dan beradab, dengan mata rantai yang saling terkait menggambarkan hubungan antarmanusia. Bintang melambangkan sila Ketuhanan Yang Maha Esa, pohon beringin melambangkan sila Persatuan Indonesia, kepala banteng melambangkan sila Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, dan padi dan kapas melambangkan sila Keadilan sosial bagi seluruh rakyat Indonesia.","id":"PPU02","kunci":1,"opsi":["Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"soal":"Rantai emas pada lambang Garuda Pancasila merupakan simbol dari sila Pancasila yang berbunyi ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Sungai Kapuas mengalir di Kalimantan Barat dan merupakan sungai terpanjang di Indonesia. Sungai Musi mengalir di Sumatera, Sungai Bengawan Solo mengalir di Jawa, sedangkan Sungai Mahakam dan Sungai Barito juga mengalir di Kalimantan tetapi lebih pendek daripada Sungai Kapuas.","id":"PPU03","kunci":4,"opsi":["Sungai Musi","Sungai Bengawan Solo","Sungai Mahakam","Sungai Barito","Sungai Kapuas"],"soal":"Sungai terpanjang di Indonesia yang mengalir di Pulau Kalimantan adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Fotosintesis mengubah karbon dioksida dan air menjadi glukosa dengan bantuan energi cahaya matahari dan klorofil, dan oksigen dilepaskan sebagai hasil samping. Karbon dioksida merupakan bahan yang diperlukan, bukan hasil fotosintesis, dan nitrogen maupun protein bukan hasil utama proses ini.","id":"PPU04","kunci":0,"opsi":["Glukosa dan oksigen","Nitrogen dan hidrogen","Karbon monoksida dan air","Protein dan nitrogen","Oksigen dan karbon dioksida"],"soal":"Dalam proses fotosintesis, tumbuhan menggunakan karbon dioksida, air, dan energi cahaya matahari. Hasil utama dari proses tersebut adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Tari Saman berasal dari masyarakat Gayo di Aceh dan dikenal dengan gerakan yang cepat, serempak, dan kompak disertai syair. Tari Kecak berasal dari Bali, Tari Piring berasal dari Sumatera Barat, dan Tari Jaipong berasal dari Jawa Barat.","id":"PPU05","kunci":2,"opsi":["Bali","Sumatera Barat","Aceh","Jawa Barat","Sulawesi Selatan"],"soal":"Tari Saman, tarian tradisional dengan gerakan cepat dan kompak yang diiringi syair, berasal dari daerah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Bacaan menggambarkan kebun komunitas sebagai sumber bahan pangan segar berbiaya rendah, sarana belajar bagi anak-anak dan kegiatan bagi warga lanjut usia, serta ruang bertemu yang memperkuat hubungan antar-tetangga. Manfaat-manfaat tersebut dirangkum dalam gagasan bahwa kebun komunitas memberi manfaat pangan, pembelajaran, dan hubungan sosial. Pembahasan tentang sayuran murah saja, kebutuhan kegiatan bagi kelompok usia tertentu saja, perubahan lahan kosong, atau jarangnya warga bertegur sapa hanya mencakup sebagian isi bacaan.","id":"PBM01","kunci":2,"opsi":["Kebun komunitas hanya bermanfaat untuk menyediakan sayuran murah bagi warga kota dan tidak memberi manfaat lain sama sekali.","Anak-anak dan warga lanjut usia membutuhkan kegiatan baru di lingkungan padat.","Kebun komunitas memberi manfaat pangan, pembelajaran, dan hubungan sosial bagi warga kota.","Lahan kosong di kota sebaiknya diubah menjadi ruang pertemuan warga.","Warga kota jarang bertegur sapa karena kesibukan dan kepadatan lingkungan."],"soal":"Di tengah kepadatan kota, kebun komunitas tumbuh di lahan kosong yang semula tidak terpakai. Warga menanam sayuran, rempah, dan bunga secara bersama-sama, lalu membagi hasil panen kepada anggota kelompok. Kegiatan ini tidak hanya menyediakan bahan pangan segar dengan biaya rendah, tetapi juga menciptakan ruang bertemu bagi tetangga yang sebelumnya jarang bertegur sapa. Anak-anak belajar mengenal tanaman dan proses tumbuhnya secara langsung, sementara warga lanjut usia menemukan kegiatan yang membuat mereka tetap aktif. Dengan demikian, kebun komunitas menjadi tempat belajar, bekerja sama, dan menjaga hubungan sosial di lingkungan yang padat. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Jumlah peminjam meningkat dua kali lipat dan sebagian besar peminjam baru adalah warga yang sebelumnya tidak pernah datang ke perpustakaan desa. Contoh Ibu Ratna dan anaknya menunjukkan tablet dipakai untuk membaca berita, mencari resep, mengerjakan tugas, dan menonton video pelajaran. Hal itu menunjukkan tablet membantu perpustakaan keliling menjangkau warga yang sebelumnya tidak terlayani. Bacaan tetap menyebut buku cetak masih dibawa, tidak menyatakan semua warga mahir, tidak membatasi layanan pada dua kelompok saja, dan tidak membandingkan pentingnya tablet dengan petugas.","id":"PBM02","kunci":4,"opsi":["Buku cetak sudah tidak lagi dibutuhkan oleh warga Kabupaten Sariwangi.","Semua warga Kabupaten Sariwangi kini mahir menggunakan tablet, kamus daring, dan seluruh layanan perpustakaan keliling.","Perpustakaan keliling hanya melayani anak sekolah dan penjual sayur.","Tablet pinjaman lebih penting daripada petugas perpustakaan dalam layanan keliling.","Kehadiran tablet membantu perpustakaan keliling menjangkau warga yang sebelumnya tidak terlayani."],"soal":"Perpustakaan keliling di Kabupaten Sariwangi mulai membawa tablet selain buku cetak. Setiap kunjungan, petugas membantu warga memilih bacaan, mengunduh cerita anak, dan mempelajari cara menggunakan kamus daring. Ibu Ratna, seorang penjual sayur, mengaku kini membaca berita dan resep masakan melalui tablet pinjaman selama satu minggu. Anaknya memakai perangkat yang sama untuk mengerjakan tugas sekolah dan menonton video pelajaran. Petugas mencatat bahwa jumlah peminjam meningkat dua kali lipat dalam enam bulan, dan sebagian besar peminjam baru adalah warga yang sebelumnya tidak pernah datang ke perpustakaan desa. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, perubahan di pasar membuat kebiasaan lama dan kebutuhan pembeli masa kini dapat berjalan bersama: suasana tawar-menawar tetap dipertahankan, sedangkan pembayaran nontunai, harga yang jelas, dan kebersihan memenuhi kebutuhan pembeli masa kini. Makna tersebut sesuai dengan menghubungkan dua hal yang berbeda sehingga keduanya tetap berjalan berdampingan. Makna mengganti kebiasaan lama secara menyeluruh, membangun jembatan fisik, memisahkan pedagang dari pembeli, atau menunda perubahan tidak sesuai dengan isi bacaan.","id":"PBM03","kunci":0,"opsi":["menghubungkan dua hal yang berbeda sehingga keduanya tetap berjalan berdampingan","mengganti kebiasaan lama dengan kebiasaan baru secara menyeluruh tanpa menyisakan suasana pasar yang lama sama sekali","membangun jembatan fisik di area pasar tradisional","memisahkan pedagang lama dari pembeli yang terbiasa berbelanja daring","menunda perubahan agar suasana pasar tidak berubah sama sekali"],"soal":"Pasar tradisional di Kota Harapan beradaptasi dengan kebiasaan belanja yang berubah. Para pedagang mulai menerima pembayaran nontunai, menuliskan harga dengan jelas, dan menjaga kebersihan lorong dagang. Pengelola pasar menyediakan area parkir yang tertata dan jadwal pembersihan yang teratur. Perubahan ini menjembatani kebiasaan lama dan kebutuhan pembeli masa kini tanpa menghilangkan suasana tawar-menawar yang menjadi ciri pasar. Pembeli yang terbiasa berbelanja daring pun mulai kembali karena merasa nyaman, sementara pedagang lama tetap dapat mempertahankan cara berdagang yang mereka kenal selama bertahun-tahun di pasar itu. Kata 'menjembatani' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata program, menggabungkan penanda sangat dan sekali, serta mengulang gagasan penting pada air yang sangat penting. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan subjek dan predikat yang jelas, tanpa pengulangan kata dan tanpa penanda penguat ganda: program menumbuhkan kesadaran siswa akan pentingnya air dalam kehidupan sehari-hari. Susunan lain masih mempertahankan pengulangan kata program, penguat ganda, atau pengulangan gagasan penting sehingga tetap bertele-tele.","id":"PBM04","kunci":3,"opsi":["Program ini sangat baik sekali karena program ini sangat baik untuk membuat siswa-siswa sadar akan pentingnya air dalam kehidupan sehari-hari mereka.","Program yang sangat baik sekali ini adalah program yang membuat siswa menjadi sadar akan air yang penting bagi kehidupan sehari-hari.","Program ini membuat siswa-siswa menjadi sadar akan pentingnya air yang sangat penting sekali bagi kehidupan mereka yang sehari-hari.","Program ini menumbuhkan kesadaran siswa akan pentingnya air dalam kehidupan sehari-hari.","Program ini adalah program yang baik karena siswa-siswa menjadi sadar akan pentingnya air yang penting bagi kehidupan sehari-hari mereka."],"soal":"Sekolah Menengah Harapan Bangsa mengadakan program hemat air selama satu semester. Setiap kelas menugaskan dua siswa untuk memeriksa keran, mencatat penggunaan air, dan melaporkan kebocoran kepada petugas kebersihan. Guru menjelaskan cara mengukur penggunaan air dengan ember ukur dan membandingkan hasilnya setiap minggu. Hasilnya, penggunaan air sekolah menurun dan siswa menjadi lebih sadar akan pentingnya menjaga sumber daya. Program ini adalah program yang sangat baik sekali karena program ini membuat siswa-siswa menjadi sadar akan pentingnya air yang sangat penting bagi kehidupan mereka sehari-hari. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kata depan di yang menyatakan tempat ditulis terpisah dari kata yang mengikutinya sehingga bentuk yang tepat adalah di sekolah. Nama hari ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Sabtu. Kata sekolah sebagai kata umum ditulis dengan huruf kecil, dan nama bilangan tingkat kelas ditulis dengan huruf kecil. Tanda koma dipakai sebelum kata dan pada pemerincian tiga unsur atau lebih sehingga bentuk yang tepat adalah sepuluh, sebelas, dan dua belas. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan di sekolah, Sabtu, dan pemerincian yang memakai koma sebelum dan.","id":"PBM05","kunci":1,"opsi":["Kegiatan ini dilaksanakan disekolah setiap hari Sabtu dan diikuti oleh siswa kelas sepuluh, sebelas dan dua belas.","Kegiatan ini dilaksanakan di sekolah setiap hari Sabtu dan diikuti oleh siswa kelas sepuluh, sebelas, dan dua belas.","Kegiatan ini dilaksanakan di sekolah setiap hari sabtu dan diikuti oleh siswa kelas Sepuluh, Sebelas, dan Dua Belas.","Kegiatan ini dilaksanakan di Sekolah setiap hari Sabtu dan diikuti oleh siswa kelas sepuluh, sebelas, dan dua belas.","Kegiatan ini dilaksanakan disekolah setiap hari sabtu dan diikuti oleh siswa kelas sepuluh, sebelas, dan dua belas."],"soal":"(1) Karang Taruna Desa Melati mengadakan pelatihan kerajinan dari bahan bekas untuk remaja desa. (2) Pelatihan ini bertujuan melatih keterampilan tangan dan menumbuhkan kepedulian terhadap lingkungan sekitar. (3) Kegiatan ini dilaksanakan disekolah setiap hari sabtu dan diikuti oleh siswa kelas sepuluh, sebelas, dan dua belas. (4) Peserta belajar mengubah botol plastik, kardus bekas, dan kain perca menjadi tempat pensil, pot tanaman, dan tas sederhana. (5) Hasil karya terbaik dipamerkan di balai desa agar warga dapat melihat bahwa bahan bekas masih dapat dimanfaatkan dengan baik dan kreatif. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Potongan 20% dari Rp250.000 adalah Rp50.000 sehingga harga setelah potongan tersebut menjadi Rp200.000. Potongan tambahan 10% dihitung dari Rp200.000, yaitu Rp20.000, sehingga harga akhir menjadi Rp200.000 dikurangi Rp20.000, yaitu Rp180.000. Potongan tambahan tidak dihitung dari harga awal sehingga total potongan bukan 30% dari Rp250.000.","id":"PK01","kunci":3,"opsi":["Rp165.000","Rp175.000","Rp187.500","Rp180.000","Rp200.000"],"soal":"Sebuah toko menjual sepatu seharga Rp250.000. Selama promosi, harga sepatu dipotong 20%, kemudian dari harga setelah potongan tersebut diberi potongan tambahan 10%. Berapa harga akhir sepatu itu?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih perbandingan adalah 7 dikurangi 2, yaitu 5 bagian, dan selisih tersebut setara dengan 30 tahun sehingga satu bagian setara dengan 6 tahun. Jumlah perbandingan adalah 7 ditambah 2, yaitu 9 bagian, sehingga jumlah usia adalah 9 dikali 6 tahun, yaitu 54 tahun. Sebagai pemeriksaan, usia ayah adalah 42 tahun dan usia anak adalah 12 tahun, dengan selisih 30 tahun.","id":"PK02","kunci":1,"opsi":["48 tahun","54 tahun","60 tahun","66 tahun","72 tahun"],"soal":"Perbandingan usia seorang ayah dan anaknya adalah 7:2. Selisih usia keduanya adalah 30 tahun. Berapa jumlah usia ayah dan anak tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih antarbilangan yang berurutan adalah 4, 6, 8, dan 10, sehingga selisih bertambah 2 setiap langkah. Selisih berikutnya adalah 12 sehingga bilangan berikutnya adalah 30 ditambah 12, yaitu 42. Pola yang sama tampak dari bentuk perkalian n dikali n tambah 1: 1 dikali 2 sama dengan 2, 2 dikali 3 sama dengan 6, 3 dikali 4 sama dengan 12, 4 dikali 5 sama dengan 20, 5 dikali 6 sama dengan 30, dan 6 dikali 7 sama dengan 42.","id":"PK03","kunci":4,"opsi":["36","38","40","41","42"],"soal":"Perhatikan barisan bilangan berikut: 2, 6, 12, 20, 30, ... Bilangan berikutnya dalam barisan tersebut adalah ...","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Misalkan lebar persegi panjang adalah l cm sehingga panjangnya adalah (l + 5) cm. Keliling sama dengan 2 dikali jumlah panjang dan lebar sehingga 2 dikali (2l + 5) sama dengan 38. Dari persamaan tersebut diperoleh 2l + 5 sama dengan 19, lalu 2l sama dengan 14, sehingga l sama dengan 7. Panjangnya adalah 12 cm dan luasnya adalah 12 dikali 7, yaitu 84 cm².","id":"PK04","kunci":0,"opsi":["84 cm²","70 cm²","77 cm²","91 cm²","96 cm²"],"soal":"Panjang sebuah persegi panjang adalah 5 cm lebih panjang dari lebarnya. Jika keliling persegi panjang tersebut adalah 38 cm, berapa luasnya?","subtes":"Pengetahuan Kuantitatif"},{"id":"PK05","subtes":"Pengetahuan Kuantitatif","soal":"Lima karung beras memiliki berat berturut-turut 48 kg, 52 kg, 50 kg, 46 kg, dan 54 kg. Berapa rata-rata berat satu karung beras tersebut?","opsi":["48 kg","49 kg","50 kg","51 kg","52 kg"],"kunci":2,"bahas":"Jumlah berat kelima karung adalah 48 + 52 + 50 + 46 + 54 = 250 kg. Rata-rata berat satu karung diperoleh dengan membagi 250 kg dengan 5, yaitu 50 kg."},{"bahas":"Teks membahas berbagai manfaat taman: menurunkan suhu, menyerap debu, menjadi habitat burung, serta menjadi tempat istirahat, olahraga, dan interaksi warga, lalu menyimpulkan bahwa menjaga taman berarti menjaga kualitas hidup bersama. Gagasan utamanya mencakup peran lingkungan dan peran sosial ruang hijau, bukan hanya satu manfaat atau keindahan semata.","id":"LBI01","kunci":2,"opsi":["Taman kota hanya berfungsi sebagai penghias kota agar terlihat indah.","Warga kota perlu berolahraga ringan setiap hari agar merasa tenang.","Ruang hijau kota penting bagi lingkungan dan kualitas hidup warga.","Burung membutuhkan pepohonan di taman sebagai tempat bersarang.","Penelitian di beberapa kota membuktikan warga dekat taman selalu sehat."],"soal":"Di tengah kota yang padat, taman kecil sering dianggap sekadar pelengkap keindahan. Padahal, ruang hijau semacam itu memiliki peran yang jauh lebih penting bagi warga. Pepohonan membantu menurunkan suhu udara, menyerap debu, dan menyediakan tempat bagi burung untuk bersarang. Bagi manusia, taman menjadi tempat beristirahat sejenak dari kebisingan, berolahraga ringan, atau sekadar berbincang dengan tetangga. Penelitian sederhana di beberapa kota menunjukkan warga yang tinggal dekat taman cenderung lebih sering berjalan kaki dan merasa lebih tenang. Oleh karena itu, menjaga taman bukan sekadar urusan keindahan, melainkan bagian dari menjaga kualitas hidup bersama. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan informasi daring bermanfaat tetapi belum tentu benar, gejala mirip dapat berasal dari penyebab berbeda, dan diagnosis membutuhkan pemeriksaan langsung. Teks juga menganjurkan informasi daring dipakai sebagai bahan awal untuk bertanya, disertai pemeriksaan sumber, perbandingan rujukan tepercaya, dan konsultasi dengan tenaga kesehatan.","id":"LBI02","kunci":4,"opsi":["Semua informasi kesehatan di internet salah dan tidak boleh dibaca sama sekali.","Gejala yang sama selalu berasal dari penyebab yang sama sehingga pengobatannya sama.","Membaca gejala di internet sudah cukup untuk menentukan diagnosis seseorang.","Unggahan yang berbahasa meyakinkan dapat dipastikan kebenarannya tanpa memeriksa sumber.","Informasi daring sebaiknya dipakai sebagai bahan bertanya dan diperiksa kebenarannya."],"soal":"Kemudahan mencari informasi kesehatan di internet membawa manfaat sekaligus risiko. Seseorang dapat membaca gejala suatu penyakit dalam hitungan detik, tetapi penjelasan yang dibacanya belum tentu benar atau sesuai dengan kondisinya. Banyak unggahan disusun tanpa rujukan jelas, menggunakan bahasa yang meyakinkan, dan mengajak pembaca mencoba pengobatan tertentu. Padahal, gejala yang mirip dapat berasal dari penyebab yang berbeda, sehingga penanganan yang tepat hanya dapat ditentukan setelah pemeriksaan langsung. Karena itu, informasi daring sebaiknya diposisikan sebagai bahan awal untuk bertanya, bukan sebagai pengganti diagnosis. Memeriksa sumber, membandingkan beberapa rujukan tepercaya, dan berkonsultasi dengan tenaga kesehatan adalah langkah yang lebih aman. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan perubahan cara petugas perpustakaan keliling dan bertambahnya anak yang datang setelah membaca disajikan secara menyenangkan, lalu menarik simpulan bahwa minat baca tumbuh dari pengalaman yang menyenangkan. Cerita tersebut berfungsi sebagai contoh yang mendukung simpulan tersebut.","id":"LBI03","kunci":0,"opsi":["Menunjukkan bahwa pengalaman membaca yang menyenangkan menumbuhkan minat baca anak.","Membuktikan bahwa semua anak desa tidak tertarik pada buku bergambar.","Menjelaskan jadwal kunjungan perpustakaan keliling di setiap desa.","Mengajak semua petugas perpustakaan mengubah suara saat membacakan cerita.","Membandingkan minat bermain di lapangan dengan minat membaca di perpustakaan tetap."],"soal":"Di sebuah desa, perpustakaan keliling datang seminggu sekali membawa kotak-kotak buku. Awalnya, hanya sedikit anak yang mendekat karena mereka lebih tertarik bermain di lapangan. Petugas perpustakaan kemudian mengubah cara kerjanya: ia membacakan satu cerita pendek dengan suara yang berubah-ubah, lalu membiarkan anak-anak memilih buku bergambar sendiri. Dalam beberapa minggu, jumlah anak yang datang bertambah dan mereka mulai saling bercerita tentang buku yang dibaca. Pengalaman ini menunjukkan bahwa minat baca tidak selalu tumbuh dari ajakan, melainkan dari pengalaman yang menyenangkan. Ketika membaca terasa seperti bermain, anak-anak datang bukan karena disuruh, melainkan karena ingin tahu. Apa tujuan penulis menyajikan pengalaman perpustakaan keliling dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Rani membersihkan selokan tetangga tanpa diminta dan menjelaskan alasannya secara sederhana, lalu tetangga lain perlahan ikut membersihkan bagian depan rumah masing-masing tanpa perintah, sehingga kebiasaan bersih terus berjalan tanpa pengumuman atau jadwal. Rangkaian peristiwa tersebut menyiratkan pengaruh teladan yang konsisten terhadap perilaku orang lain.","id":"LBI04","kunci":3,"opsi":["Kebersihan gang hanya dapat dijaga melalui pengumuman resmi dan jadwal tertulis.","Rani menyapu selokan karena ia ditugaskan secara resmi oleh seluruh tetangga.","Tetangga yang lanjut usia tidak mampu lagi menjaga kebersihan rumahnya sendiri.","Teladan yang konsisten dapat mendorong orang lain ikut bertindak tanpa perintah.","Genangan air setelah hujan deras hanya dapat diatasi dengan membersihkan selokan setiap pagi."],"soal":"Setiap pagi, Rani menyapu halaman rumahnya sebelum berangkat bekerja. Ia tidak hanya menyapu bagian depan rumahnya sendiri, melainkan juga selokan kecil di depan rumah tetangga yang sudah lanjut usia. Ketika ditanya alasannya, Rani hanya menjawab bahwa air harus mengalir agar tidak menggenang. Tetangga-tetangga lain awalnya memperhatikan dari jauh, tetapi lama-kelamaan beberapa dari mereka ikut membersihkan bagian depan rumah masing-masing tanpa diminta. Kini, setiap akhir pekan, gang itu terlihat lebih bersih dan tidak ada lagi genangan air setelah hujan deras. Tidak ada pengumuman resmi, tidak ada jadwal tertulis, tetapi kebiasaan itu terus berjalan. Apa makna tersirat dari tindakan Rani dan perubahan perilaku tetangga dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat penolak mengabaikan perbedaan skala dan kebiasaan, lalu menjelaskan kantong plastik dibagikan dalam jumlah sangat besar, dipakai sebentar, dan pengurangannya dapat melatih kebiasaan membawa tas sendiri. Kelemahannya terletak pada cara menilai kebijakan tanpa mempertimbangkan skala pemakaian dan perubahan kebiasaan tersebut.","id":"LBI05","kunci":1,"opsi":["Anggapan bahwa larangan tersebut akan menghapus seluruh sampah plastik dalam waktu singkat.","Penilaian yang mengabaikan skala pemakaian dan pengaruh kebiasaan yang berubah.","Keyakinan bahwa kantong plastik dipakai dalam waktu lama sebelum akhirnya dibuang.","Gagasan bahwa toko sudah menyediakan tas ramah lingkungan sebelum larangan diberlakukan.","Dugaan bahwa warga menolak membawa tas sendiri dalam keadaan apa pun."],"soal":"Sebagian orang berpendapat bahwa larangan kantong plastik sekali pakai tidak akan mengubah apa pun karena sampah plastik juga berasal dari kemasan lain. Pendapat ini mengabaikan perbedaan skala dan kebiasaan. Kantong plastik dibagikan dalam jumlah sangat besar setiap hari, dipakai hanya beberapa menit, lalu dibuang. Mengurangi satu jenis sampah yang paling sering dipakai dapat melatih warga membawa tas sendiri dan membuat toko menyediakan pilihan yang lebih ramah lingkungan. Perubahan kecil yang dilakukan banyak orang secara terus-menerus dapat mengurangi jumlah sampah secara nyata. Karena itu, menilai kebijakan hanya dari satu jenis kemasan yang tersisa adalah cara menilai yang tidak lengkap. Menurut teks, kelemahan pendapat yang menolak larangan kantong plastik terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan pertemuan bulanan tempat warga belajar memperbaiki pakaian sendiri dengan bantuan relawan, lalu menyebutkan tujuannya: menyelamatkan pakaian dari tempat sampah, mempelajari keterampilan berguna, menghabiskan waktu bersama, dan menumbuhkan rasa percaya diri. Gagasan utama mencakup seluruh tujuan tersebut, bukan hanya satu rincian.","id":"LBE01","kunci":3,"opsi":["Volunteers should repair all the clothes for visitors so that the work is finished as quickly as possible.","Most people in the neighborhood do not know how to use a needle correctly.","Monthly gatherings are the best way to make new friends in any neighborhood.","A sewing gathering helps residents learn repair skills, reduce waste, and support one another.","Broken zippers and loose buttons are the most common clothing problems today."],"soal":"In a small neighborhood, a group of residents started a monthly gathering where people bring torn clothes, loose buttons, and broken zippers. Volunteers who know basic sewing show visitors how to fix the items themselves instead of doing the work for them. At first, many visitors felt unsure because they had never held a needle. After a few meetings, however, they began to arrive with friends and to help newcomers. The organizers say the goal is not only to save clothes from being thrown away. They also want neighbors to learn a useful skill, spend time together, and feel more confident about solving small problems on their own. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Kata tersebut menggambarkan kemajuan kebun Lina yang diawali beberapa daun hijau, dilanjutkan tunas kecil, dan kemudian buah tomat. Gambaran tersebut menunjukkan kemajuan yang kecil dan bertahap, bukan kemajuan yang mendadak, sempurna, membingungkan, atau sangat cepat.","id":"LBE02","kunci":1,"opsi":["sudden and surprising","small and gradual","complete and perfect","difficult and confusing","rapid and impressive"],"soal":"When Lina began keeping a small vegetable garden behind her house, she expected quick results. The soil was dry, the sunlight was uneven, and several young plants died in the first month. Instead of giving up, she asked an experienced neighbor for advice, watered the plants early in the morning, and added compost little by little. Progress was modest at first: a few green leaves, then small shoots, then the first tomatoes. Lina learned that a garden does not reward impatience. It rewards steady attention, careful observation, and a willingness to adjust when conditions change. The word 'modest' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan rak tetap penuh setelah enam bulan, seseorang menambahkan bangku dan catatan agar tempat dijaga tetap rapi, dan anak-anak mampir untuk membaca bersama. Teks juga menyatakan dewan berencana membangun tempat serupa lagi dengan aturan sederhana yang sama. Rangkaian fakta tersebut menunjukkan warga menjaga perpustakaan bersama dengan baik sehingga gagasan tersebut diperluas.","id":"LBE03","kunci":4,"opsi":["The town council hired staff to guard the tiny library day and night.","Children in the town had never read any books at all before the library was built.","All officials in the town supported the library idea from the beginning.","Residents were required to pay a fine if they kept a book for too long.","Residents cared for the shared library, encouraging the council to expand it."],"soal":"A town council decided to turn an unused bus shelter into a tiny free library. Residents could take a book and leave another one in its place, with no cards, no fines, and no staff. Some officials worried that the books would disappear quickly or that the shelter would be damaged. After six months, however, the shelves were still full, and someone had added a small bench and a handwritten note asking visitors to keep the place tidy. Local teachers noticed that children stopped there on their way home and often read together for a few minutes. The council now plans to build two more shelters, using the same simple rules. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan dapur komunitas mengumpulkan sayuran yang tidak dapat dijual karena bercak kecil atau bentuk yang tidak biasa, padahal sayuran tersebut masih segar dan banyak pembeli melewatkannya. Alasan tersebut berkaitan dengan penampilan sayuran, bukan dengan keamanan pangan, pembayaran, permintaan relawan, atau perintah dewan kota.","id":"LBE04","kunci":0,"opsi":["Because shoppers avoid vegetables with small marks or odd shapes, although they are still fresh.","Because the vegetables have become unsafe to eat and cannot be sold anywhere.","Because the community kitchen pays sellers a high price for perfect vegetables.","Because volunteers asked sellers to stop selling vegetables at the local market.","Because the town council ordered all local sellers to donate their leftover food every single week."],"soal":"Every Saturday morning, a community kitchen in a coastal town collects vegetables that local sellers cannot sell because of small marks or unusual shapes. The vegetables are still fresh, but many shoppers pass them by. Volunteers wash, chop, and cook them into soup, which is shared free of charge with anyone who comes. The kitchen keeps careful records of how much food it receives and how many bowls it serves. Last month, it served more than four hundred bowls and threw away almost nothing. The organizers hope the kitchen will change how people think about imperfect food and show that good meals do not require perfect ingredients. According to the passage, why do local sellers give their vegetables to the community kitchen?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Daniel yang mulai belajar piano di usia dewasa, berkembang perlahan, dan sering melakukan kesalahan yang sama, tetapi gurunya menekankan perbaikan kecil dan Daniel akhirnya menikmati latihan serta menilai keberhasilan dari kemauan untuk kembali berlatih. Cerita tersebut menggambarkan nilai usaha yang terus-menerus dan perbaikan kecil, bukan kecepatan belajar, rasa malu, penguasaan penuh, atau cara memilih guru.","id":"LBE05","kunci":2,"opsi":["To argue that adults learn musical instruments faster than younger students in every case.","To suggest that piano lessons are embarrassing and should always be taken alone.","To show that steady effort and small improvements matter more than age or speed.","To prove that anyone can master the piano completely within one year.","To explain the best method for choosing a piano teacher for adult learners."],"soal":"At forty-two, Daniel decided to learn the piano after years of telling himself he was too old to start. His progress was slow. He practiced short pieces, made the same mistakes repeatedly, and sometimes felt embarrassed during lessons with younger students. His teacher, however, focused on small improvements: a steadier rhythm, a smoother transition, a section played without stopping. After a year, Daniel could play three simple songs from start to finish and had begun to enjoy practicing for its own sake. He still makes mistakes, but he no longer measures success by speed. He measures it by whether he returns to the piano the next day. What is the author's purpose in telling Daniel's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 2 jam, 3 oven menghasilkan 240 roti, sehingga satu oven menghasilkan 80 roti dalam 2 jam atau 40 roti dalam 1 jam. Untuk 5 oven selama 3 jam: 5 x 3 x 40 = 600 roti.","id":"PM01","kunci":3,"opsi":["480","540","660","600","720"],"soal":"Sebuah toko roti memiliki 3 oven yang bekerja dengan laju sama. Ketiga oven tersebut menghasilkan 240 roti dalam 2 jam. Jika toko menambah oven menjadi 5 oven dan semuanya bekerja selama 3 jam dengan laju yang sama, berapa roti yang dihasilkan?","subtes":"Penalaran Matematika"},{"bahas":"Setiap suku diperoleh dengan menggandakan suku sebelumnya lalu menambah 1: 5 x 2 + 1 = 11, 11 x 2 + 1 = 23, 23 x 2 + 1 = 47, dan 47 x 2 + 1 = 95. Suku berikutnya adalah 95 x 2 + 1 = 191.","id":"PM02","kunci":0,"opsi":["191","183","189","195","187"],"soal":"Perhatikan barisan bilangan berikut: 5, 11, 23, 47, 95, ... Bilangan berikutnya dalam barisan tersebut adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Jumlah seluruh nilai adalah 6 + 7 + 7 + 8 + 8 + 8 + 9 + 9 + 10 + 10 = 82, sehingga rata-ratanya 82 : 10 = 8,2. Data sudah terurut dan dua nilai di tengah keduanya 8, sehingga mediannya 8. Selisih rata-rata dan median adalah 8,2 - 8 = 0,2.","id":"PM03","kunci":4,"opsi":["0","0,4","0,5","0,8","0,2"],"soal":"Nilai ulangan 10 siswa adalah sebagai berikut: 6, 7, 7, 8, 8, 8, 9, 9, 10, 10. Selisih antara rata-rata dan median dari data tersebut adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Peluang mendapat bola merah pada pengambilan awal adalah 4 dari 10. Setelah satu bola merah terambil tanpa pengembalian, tersisa 3 bola merah dari 9 bola. Mengalikan peluang tersebut: 4/10 x 3/9 = 12/90 = 2/15.","id":"PM04","kunci":1,"opsi":["1/5","2/15","1/6","3/20","1/10"],"soal":"Sebuah kotak berisi 4 bola merah, 3 bola biru, dan 3 bola hijau yang bentuk dan ukurannya sama. Dua bola diambil satu demi satu secara acak tanpa pengembalian. Peluang bahwa dua bola yang terambil keduanya berwarna merah adalah ....","subtes":"Penalaran Matematika"},{"bahas":"Jumlah pengunjung Senin sampai Jumat adalah 120 + 150 + 135 + 180 + 165 = 750, sehingga rata-rata per hari adalah 750 : 5 = 150. Pengunjung hari Sabtu 20% lebih banyak, yaitu 150 + 20/100 x 150 = 150 + 30 = 180.","id":"PM05","kunci":2,"opsi":["168","174","180","186","192"],"soal":"Jumlah pengunjung sebuah perpustakaan selama lima hari tercatat sebagai berikut: Senin 120 orang, Selasa 150 orang, Rabu 135 orang, Kamis 180 orang, dan Jumat 165 orang. Pada hari Sabtu, jumlah pengunjung diperkirakan 20% lebih banyak daripada rata-rata pengunjung per hari selama lima hari tersebut. Perkiraan jumlah pengunjung pada hari Sabtu adalah ....","subtes":"Penalaran Matematika"}];
